G=load(); print(sorted(G)); print(json.dumps(G))

def blocks(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen[a][b]=True; cells.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W: st.append((x,y))
                out.append((col,cells))
    return out
